#!/usr/bin/env node
/*
 * Build the modules this playground hosts itself.
 *
 * There is no community server yet, so the server is this deployment: each
 * file in playground/modules is bundled to one self-contained ES module and
 * dropped beside the app, where the Modules dialog can offer it in one click.
 *
 * They are NOT part of the app's bundle, deliberately. A module fetched from a
 * URL is the path a stranger's module will take, and hosting ours the same way
 * is what keeps that path honest: if it breaks, it breaks for us first.
 *
 * The catalogue is generated by IMPORTING each built file and asking it what
 * it is, rather than from a list written by hand. A list beside the modules is
 * a list that disagrees with them by next month.
 */
import { build } from 'esbuild';
import { mkdir, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const SOURCE = 'playground/modules';
const [target = 'dist/demo/browser'] = process.argv.slice(2);
const out = join(target, 'modules');

await mkdir(out, { recursive: true });

const sources = (await readdir(SOURCE)).filter(name => name.endsWith('.ts'));

if (!sources.length) {
  console.error(`No modules in ${SOURCE}`);
  process.exit(1);
}

const catalogue = [];

for (const source of sources) {
  const name = source.replace(/\.ts$/, '');
  const file = join(out, `${name}.js`);

  await build({
    entryPoints: [join(SOURCE, source)],
    outfile: file,
    bundle: true,
    format: 'esm',
    target: 'es2022',
    platform: 'browser',
    minify: true,
    /*
     * rxjs travels WITH the module. It is the one runtime a node may genuinely
     * need, the editor never tests an Observable with instanceof, and the
     * alternative — expecting the host page to share its copy — is an import
     * map, which is exactly the machinery a single file is meant to avoid.
     */
    legalComments: 'none',
  });

  // Ask the module what it is. It is a browser file, but nothing at its top
  // level touches the DOM beyond a guarded style tag, so importing is safe.
  const module = (await import(pathToFileURL(resolve(file)).href)).default;

  catalogue.push({
    // Relative to the CATALOGUE, not to the app: the whole folder can be
    // moved or mirrored and the list still points at its own neighbours.
    url: `${name}.js`,
    title: module.name,
    description: module.description ?? '',
    prefix: module.prefix,
    types: Object.keys(module.types).length,
  });

  console.log(`${source} → ${file} (${module.name}, ${Object.keys(module.types).length} types)`);
}

await writeFile(join(out, 'index.json'), `${JSON.stringify(catalogue, null, 2)}\n`);
console.log(`${out}/index.json: ${catalogue.length} module(s)`);
